DO $$ DECLARE _t text; BEGIN SELECT command INTO _t FROM cron.job WHERE jobname = 'process-first-billing'; IF _t IS NULL OR position('/functions/v1/process-first-billing' IN _t) = 0 THEN RAISE EXCEPTION 'process-first-billing template not found'; END IF; PERFORM cron.schedule('generate-monthly-invoices', '0 6 * * *', replace(_t, '/functions/v1/process-first-billing', '/functions/v1/generate-invoices')); PERFORM cron.schedule('daily-payment-reminders', '0 9 * * *', replace(_t, '/functions/v1/process-first-billing', '/functions/v1/payment-reminders')); END $$;